Sure, here's a step-by-step process to achieve this in C#:
1. Create a dictionary to store the number of vowels in each country's name.
2. Loop through the list of countries and count the number of vowels in each name.
3. Add each country and its corresponding vowel count to the dictionary.
4. Sort the dictionary by value (the vowel count), then by key (the country name).
5. Loop through the sorted dictionary and print out the country names in alphabetical order based on the number of vowels in their name.
Here's the C# code to automate this process:
```
using System;
using System.Collections.Generic;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        List<string> countries = new List<string> { "Uzbekistan", "Brazil", "Iceland", "Zambia", "Malaysia", "Kyrgyzstan", "Austria", "Nicaragua" };
        Dictionary<string, int> vowelCounts = new Dictionary<string, int>();
        // Count the number of vowels in each country's name and add to dictionary
        foreach (string country in countries)
        {
            int count = 0;
            foreach (char c in country.ToLower())
            {
                if ("aeiou".Contains(c))
                {
                    count++;
                }
            }
            vowelCounts.Add(country, count);
        }
        // Sort the dictionary by value (vowel count), then by key (country name)
        var sortedDict = from entry in vowelCounts orderby entry.Value, entry.Key select entry;
        // Print out the country names in alphabetical order based on the number of vowels in their name
        foreach (KeyValuePair<string, int> pair in sortedDict)
        {
            Console.WriteLine(pair.Key);
        }
    }
}
```
