num = input("Enter a three-digit number: ");
% Extract the individual digits of the number
digit1 = floor(num/100);
digit2 = floor(mod(num,100)/10);
digit3 = mod(num,10);
% Calculate the sum of the individual digits raised to the power of the total number of digits
sum = digit1^3 + digit2^3 + digit3^3;
% Check if the sum is equal to the original number
if sum == num
    disp("The number is an Armstrong number.");
else
    disp("The number is not an Armstrong number.");
end
```
