    F_b = (rho_g - rho_a)*V_g*g;
end
% Function for calculating drag force
function F_d = drag_force(rho_a,v)
    F_d = 0.5*rho_a*Cd*A*v^2;
end
% Function for calculating temperature and pressure
function [dT,dP] = temp_pressure(h,T,P)
    dT = -g*T/(R*h);
    dP = -rho_0*g*T/(R*h)*((1+(g*h)/(R*T_0)))^(1/0.0065);
end
% Function for calculating velocity and altitude
function [dh,dv] = velocity_altitude(t,y)
    h = y(1);
    v = y(2);
    T = y(3);
    P = y(4);

    % Calculate air density
    rho_a = air_density(h,T,P);

    % Calculate volume of balloon
    V_b = (m_g*R*T)/(P*m_b);

    % Calculate volume of displaced air
    V_g = V_b - (m_g/m_b)*V_b;

    % Calculate density of displaced air
    rho_g = P/(R*T);

    % Calculate buoyancy force
    F_b = buoyancy_force(rho_g,rho_a,V_g);

    % Calculate drag force
    F_d = drag_force(rho_a,v-V_w(1));

    % Calculate total force
    F = F_b - F_d - m_b*g;

    % Calculate temperature and pressure
    [dT,dP] = temp_pressure(h,T,P);

    % Calculate acceleration
    a = F/m_b;

    % Calculate velocity and altitude
    dv = a;
    dh = v;
end
% Solve differential equations
y0 = [h0; v0; T0; P0];
[t,y] = ode45(@velocity_altitude,tspan,y0,options);
% Plot altitude, velocity, temperature, and pressure
subplot(2,2,1);
plot(t,y(:,1));
xlabel('Time (s)');
ylabel('Altitude (m)');
title('Altitude vs Time');
subplot(2,2,2);
plot(t,y(:,2));
xlabel('Time (s)');
ylabel('Velocity (m/s)');
title('Velocity vs Time');
subplot(2,2,3);
plot(t,y(:,3));
xlabel('Time (s)');
ylabel('Temperature (K)');
title('Temperature vs Time');
subplot(2,2,4);
plot(t,y(:,4));
xlabel('Time (s)');
ylabel('Pressure (Pa)');
title('Pressure vs Time');
```
This code uses the `ode45` function to solve the differential equations that describe the motion of the hot-air balloon. The `velocity_altitude` function calculates the velocity and altitude of the balloon at each time step, taking into account the forces of buoyancy, drag, and gravity, as well as the impact of temperature and pressure on the density of the air. The `air_density`, `buoyancy_force`, `drag_force`, and `temp_pressure` functions are used to calculate the air density, buoyancy force, drag force, and changes in temperature and pressure, respectively.
The code plots the altitude, velocity, temperature, and pressure of the balloon over time. The wind velocity is set to [10; 0; 0] in this example, but can be adjusted to simulate different wind conditions.

