import java.util.*;
public class Main {
    public static void main(String[] args) {
        int[] array1 = {2, 3, 7, 8};
        int[] array2 = {3, 2, 8, 7};
        Set<Integer> set1 = new HashSet<Integer>();
        Set<Integer> set2 = new HashSet<Integer>();
        // Add elements of array1 to set1
        for (int i = 0; i < array1.length; i++) {
            set1.add(array1[i]);
        }
        // Add elements of array2 to set2
        for (int i = 0; i < array2.length; i++) {
            set2.add(array2[i]);
        }
        // Find the set difference between set1 and set2
        set1.removeAll(set2);
        // Print the number of distinct elements between array1 and array2
        System.out.println("Number of distinct elements: " + set1.size());
    }
}
```
