```c++
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"
using namespace rapidjson;
int main() {
    // create a JSON document
    Document document;
    document.SetObject();
    // create an array of UN member objects
    Value members(kArrayType);
    // add UN member objects to the array
    Value member(kObjectType);
    member.AddMember("official_name", "United States of America", document.GetAllocator());
    member.AddMember("short_name", "USA", document.GetAllocator());
    member.AddMember("region", "North America", document.GetAllocator());
    members.PushBack(member, document.GetAllocator());
    member["official_name"] = "United Kingdom of Great Britain and Northern Ireland";
    member["short_name"] = "United Kingdom";
    member["region"] = "Europe";
    members.PushBack(member, document.GetAllocator());
    member["official_name"] = "Republic of India";
    member["short_name"] = "India";
    member["region"] = "Asia";
    members.PushBack(member, document.GetAllocator());
    // add the array of UN members to the document
    document.AddMember("members", members, document.GetAllocator());
    // convert the JSON document to a string
    StringBuffer buffer;
    Writer<StringBuffer> writer(buffer);
    document.Accept(writer);
    // print the JSON string
    std::cout << buffer.GetString() << std::endl;
    return 0;
}
```
This code creates a JSON document with an array of UN member objects, each containing their official name, short name, and region. You can add more member objects to the array by creating a new `Value` object and using the `PushBack` method to add it to the array. Finally, the JSON document is converted to a string and printed to the console.

