import java.util.*;
public class FruitSorter {
   public static void main(String args[]) {

      List<String> fruits = new ArrayList<String>();
      fruits.add("Pineapple");
      fruits.add("Watermelon");
      fruits.add("Grapes");

      // Define a map to store the sweetness levels of each fruit
      Map<String, Integer> sweetnessLevels = new HashMap<String, Integer>();
      sweetnessLevels.put("Pineapple", 5);
      sweetnessLevels.put("Watermelon", 8);
      sweetnessLevels.put("Grapes", 7);

      // Sort the list of fruits based on their sweetness levels
      Collections.sort(fruits, new Comparator<String>() {
         public int compare(String fruit1, String fruit2) {
            return sweetnessLevels.get(fruit2) - sweetnessLevels.get(fruit1);
         }
      });

      // Output the sorted list
      System.out.println("Sorted list of fruits based on sweetness:");
      for (String fruit : fruits) {
         System.out.println(fruit);
      }
   }
}

