And here is sample code in Java that implements the same algorithm:
```
import java.util.Arrays;
import java.util.Random;
public class QuickSort {
    private static final int INSERTION_THRESHOLD = 10;
    public static void main(String[] args) {
        int[] arr = new int[10000];
        Random rand = new Random();
        for (int i = 0; i < arr.length; i++) {
            arr[i] = rand.nextInt(100);
        }
        quicksort(arr, 0, arr.length);
        System.out.println(Arrays.toString(arr));
    }
    public static void quicksort(int[] arr, int start, int end) {
        if (start >= end) {
            return;
        }
        if (end - start < INSERTION_THRESHOLD) {
            // Switch to insertion sort for small subarrays
            insertionsort(arr, start, end);
            return;
        }
        int pivot = median_of_three(arr, start, end);
        int i = start;
        int j = end - 1;
        while (i <= j) {
            while (arr[i] < pivot) {
                i++;
            }
            while (arr[j] > pivot) {
                j--;
            }
            if (i <= j) {
                swap(arr, i, j);
                i++;
                j--;
            }
        }
        quicksort(arr, start, j + 1);
        quicksort(arr, i, end);
    }
    public static int median_of_three(int[] arr, int start, int end) {
        int mid = (start + end) / 2;
        if (arr[start] > arr[mid]) {
            swap(arr, start, mid);
        }
        if (arr[start] > arr[end - 1]) {
            swap(arr, start, end - 1);
        }
        if (arr[mid] > arr[end - 1]) {
            swap(arr, mid, end - 1);
        }
        swap(arr, mid, end - 2);
        return arr[end - 2];
    }
    public static void insertionsort(int[] arr, int start, int end) {
        for (int i = start + 1; i < end; i++) {
            int j = i;
            while (j > start && arr[j] < arr[j - 1]) {
                swap(arr, j, j - 1);
                j--;
            }
        }
    }
    public static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
```

