```csharp
using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
class Program
{
    static void Main(string[] args)
    {
        string filePath = "shoppingList.json";
        List<Item> shoppingList = LoadShoppingList(filePath);
        while (true)
        {
            Console.WriteLine("1. View Shopping List");
            Console.WriteLine("2. Add New Item");
            Console.WriteLine("3. Remove Item");
            Console.WriteLine("4. Update Quantity");
            Console.WriteLine("5. Exit");
            Console.Write("Enter your choice: ");
            int choice = int.Parse(Console.ReadLine());
            switch (choice)
            {
                case 1:
                    ViewShoppingList(shoppingList);
                    break;
                case 2:
                    AddNewItem(shoppingList);
                    SaveShoppingList(shoppingList, filePath);
                    break;
                case 3:
                    RemoveItem(shoppingList);
                    SaveShoppingList(shoppingList, filePath);
                    break;
                case 4:
                    UpdateQuantity(shoppingList);
                    SaveShoppingList(shoppingList, filePath);
                    break;
                case 5:
                    SaveShoppingList(shoppingList, filePath);
                    return;
                default:
                    Console.WriteLine("Invalid choice!");
                    break;
            }
        }
    }
    static List<Item> LoadShoppingList(string filePath)
    {
        if (!File.Exists(filePath))
        {
            return new List<Item>();
        }
        string json = File.ReadAllText(filePath);
        return JsonConvert.DeserializeObject<List<Item>>(json);
    }
    static void SaveShoppingList(List<Item> shoppingList, string filePath)
    {
        string json = JsonConvert.SerializeObject(shoppingList);
        File.WriteAllText(filePath, json);
    }
    static void ViewShoppingList(List<Item> shoppingList)
    {
        Console.WriteLine("Shopping List:");
        Console.WriteLine("---------------");
        if (shoppingList.Count == 0)
        {
            Console.WriteLine("No items in shopping list.");
            return;
        }
        for (int i = 0; i < shoppingList.Count; i++)
        {
            Console.WriteLine($"{i + 1}. {shoppingList[i].Name} ({shoppingList[i].Quantity})");
        }
    }
    static void AddNewItem(List<Item> shoppingList)
    {
        if (shoppingList.Count >= 10)
        {
            Console.WriteLine("Shopping list is full!");
            return;
        }
        Console.Write("Enter item name: ");
        string name = Console.ReadLine();
        Console.Write("Enter item quantity: ");
        int quantity = int.Parse(Console.ReadLine());
        shoppingList.Add(new Item { Name = name, Quantity = quantity });
    }
    static void RemoveItem(List<Item> shoppingList)
    {
        Console.Write("Enter item number to remove: ");
        int index = int.Parse(Console.ReadLine()) - 1;
        if (index < 0 || index >= shoppingList.Count)
        {
            Console.WriteLine("Invalid item number!");
            return;
        }
        shoppingList.RemoveAt(index);
    }
    static void UpdateQuantity(List<Item> shoppingList)
    {
        Console.Write("Enter item number to update quantity: ");
        int index = int.Parse(Console.ReadLine()) - 1;
        if (index < 0 || index >= shoppingList.Count)
        {
            Console.WriteLine("Invalid item number!");
            return;
        }
        Console.Write("Enter new quantity: ");
        int quantity = int.Parse(Console.ReadLine());
        shoppingList[index].Quantity = quantity;
    }
}
class Item
{
    public string Name { get; set; }
    public int Quantity { get; set; }
}
```
